    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes4 interfaceId) public {
        // The reference contract supportsInterface returns true if and only if
        // interfaceId matches type(IAccessControl).interfaceId or type(IERC165).interfaceId.
        // The mutant returns true unconditionally.
        // To observe: call the original reference impl's logic separately and compare.
