pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(0, address(this), address(this));
    }

    function testFuzz_property(bytes32 role, address account) public {
        // 1. bind role so that it is not the DEFAULT_ADMIN_ROLE (0x00) which is already granted to the contract
        //    but we can still use it for fuzzing; we will grant the fuzzed role to the fuzzed account.
        vm.assume(role != bytes32(0));
        vm.assume(account != address(0));
        // 2. Grant the fuzzed role to the fuzzed account using the default admin role
        vm.startPrank(address(this));
        c.grantRole(role, account);
        vm.stopPrank();
        // 3. The reference C must return true because the role was just granted.
        assertTrue(c.hasRole(role, account));
    }
}

