contract HelperSetter {
    function setRoleAdmin(C target, bytes32 role, bytes32 adminRole) external {
        vm.prank(address(target));
        // Use low-level call to invoke private _setRoleAdmin via the public surface
        (bool success, ) = address(target).call(abi.encodeWithSignature("_setRoleAdmin(bytes32,bytes32)", role, adminRole));
        require(success, "setRoleAdmin failed");
    }
}

